function nav(){ $('#nav').innerHTML=Object.keys(labels).filter(p=>p!=='admin'||state.admin).map(p=>`<a href="#${p}" class="${state.page===p?'active':''}"><span aria-hidden="true">${icons[p]}</span><span>${labels[p]}</span></a>`).join('');$('#breadcrumb').textContent=labels[state.page]; }
