function stats(){const drafts=state.page==='drafts';return `<div class="stats">${(drafts?[["Черновики в работе",cards.filter(c=>c.kind==='draft').length,'▤'],['Можно дозаполнить',18,'↗'],['Требует человека',9,'!'],['На модерации',9,'◷']]:[['В рабочем списке',cards.filter(c=>!c.archived).length,'▦'],['Требует внимания',cards.filter(c=>['error','duplicate'].includes(c.kind)).length,'!'],['На модерации',cards.filter(c=>c.kind==='moderation').length,'◷'],['Ожидает подписи',cards.filter(c=>c.kind==='signing').length,'⌁']]).map(([name,n,icon],i)=>`<div class="stat ${i===1?'warning':''}"><div><small>${name}</small><b>${n}</b></div><span class="stat-icon" aria-hidden="true">${icon}</span></div>`).join('')}</div>`;}
function filtered(){return cards.filter(c=>{
 const q=state.query.toLowerCase();
 return (!q||[c.pn,c.gtin,c.name].some(x=>x.toLowerCase().includes(q)))&&(!state.tnved||c.tnved===state.tnved)&&(!state.owner||c.owner===state.owner)&&
 (state.filter==='archive'?c.archived:(!c.archived||c.kind==='published')&&(state.filter==='all'||state.filter==='draft'&&['draft','error','duplicate'].includes(c.kind)||state.filter==='attention'&&['error','duplicate'].includes(c.kind)||state.filter==='moderation'&&c.kind==='moderation'));
 });}
function badge(c){return `<span class="badge ${({published:'green',moderation:'blue',error:'red',duplicate:'amber',signing:'amber',pending:'blue'})[c.kind]||''}">${esc(c.external)}</span>`;}
