 $('#main').innerHTML=heading(state.page==='drafts'?'Черновики':'Карточки товаров','Общий каталог организации · опубликованные, черновые и локальные версии',`<button id="sync" title="Подключение к НК не настроено">↻ Синхронизировать</button><button class="primary" id="create">+ Создать карточку</button>`)+stats()+
 `<section class="registry" aria-label="Реестр карточек"><div class="tabs" id="filters-tabs">${[['all','Все карточки'],['draft','Черновики'],['attention','Требует внимания'],['moderation','На модерации'],['archive','Архив']].map(([id,l])=>`<button class="${state.filter===id?'active':''}" data-filter="${id}">${l}</button>`).join('')}</div><div class="filters"><input id="search" aria-label="Поиск карточек" placeholder="⌕  PN, GTIN или наименование" value="${esc(state.query)}"><select id="tnved-filter" aria-label="Фильтр ТН ВЭД"><option value="">Все ТН ВЭД</option>${[...new Set(cards.map(c=>c.tnved))].map(t=>`<option ${state.tnved===t?'selected':''}>${t}</option>`).join('')}</select><select id="owner-filter" aria-label="Фильтр ответственного"><option value="">Все ответственные</option>${['Александр','Елена','Вера'].map(x=>`<option ${state.owner===x?'selected':''}>${x}</option>`).join('')}</select><button id="columns" class="subtle">Колонки ⚙</button></div><div id="status-notice"></div><div class="table-wrap" id="table-wrap"></div><div id="bulk"></div><div id="registry-footer" class="registry-footer"></div></section>`;
 $('#search').oninput=e=>{state.query=e.target.value;state.pageNo=1;renderRows();};
